// Arquivo completo e corrigido para: src/App.js

import React, { useState, useEffect } from 'react';
// Importe os componentes de roteamento
import { Routes, Route, useNavigate, useLocation } from 'react-router-dom';
import './App.css';

// Importe todos os seus componentes de tela
import AppHeader from './components/AppHeader';
import HomePage from './components/HomePage';
import LoginScreen from './components/LoginScreen';
import SignupScreen from './components/SignupScreen';
import Dashboard from './components/Dashboard';
import PetCadastroScreen from './components/PetCadastroScreen';
import MeusPetsScreen from './components/MeusPetsScreen';
import MeuPerfilScreen from './components/MeuPerfilScreen';

// Componente auxiliar para proteger rotas
const ProtectedRoute = ({ isLoggedIn, children }) => {
    if (!isLoggedIn) {
        // Se não estiver logado, redireciona para a tela de login
        return <LoginScreen />;
    }
    return children;
};

function App() {
    const [isLoggedIn, setIsLoggedIn] = useState(false);
    const [userData, setUserData] = useState(null);
    const navigate = useNavigate(); // Hook para navegação programática
    const location = useLocation(); // Hook para saber a URL atual

    // Efeito para verificar o login ao carregar o app
    useEffect(() => {
        const token = localStorage.getItem('token');
        const savedUserData = localStorage.getItem('userData');
        if (token && savedUserData) {
            setIsLoggedIn(true);
            setUserData(JSON.parse(savedUserData));
        } else {
            // Se não há token e o usuário tenta acessar uma página protegida, força o login
            const protectedPaths = ['/dashboard', '/meus-pets', '/meu-perfil', '/cadastrar-pet'];
            if (protectedPaths.includes(location.pathname)) {
                navigate('/login');
            }
        }
    }, []); // Executa apenas uma vez

    const handleLogin = (data) => {
        setIsLoggedIn(true);
        setUserData(data);
        navigate('/'); // Navega para a home após login
    };

    const handleLogout = () => {
        localStorage.removeItem('token');
        localStorage.removeItem('userData');
        setIsLoggedIn(false);
        setUserData(null);
        navigate('/'); // Navega para a home após logout
    };

    // Função de navegação para ser passada aos componentes filhos
    const handleNavigate = (path) => {
        navigate(path);
    };

    return (
        <div className="App">
            <AppHeader
                isLoggedIn={isLoggedIn}
                userData={userData}
                onLogout={handleLogout}
                onNavigate={handleNavigate} // Passa a função de navegação
            />
            <main>
                {/* O sistema de roteamento substitui o switch case */}
                <Routes>
                    {/* Rotas Públicas */}
                    <Route path="/" element={<HomePage onNavigate={handleNavigate} isLoggedIn={isLoggedIn} userData={userData} />} />
                    <Route path="/login" element={<LoginScreen onLogin={handleLogin} onNavigate={handleNavigate} />} />
                    <Route path="/signup" element={<SignupScreen onNavigateToLogin={() => navigate('/login')} />} />

                    {/* Rotas Protegidas */}
                    <Route path="/dashboard" element={<ProtectedRoute isLoggedIn={isLoggedIn}><Dashboard userData={userData} /></ProtectedRoute>} />
                    <Route path="/meus-pets" element={<ProtectedRoute isLoggedIn={isLoggedIn}><MeusPetsScreen /></ProtectedRoute>} />
                    <Route path="/meu-perfil" element={<ProtectedRoute isLoggedIn={isLoggedIn}><MeuPerfilScreen onNavigateToHome={() => navigate('/')} /></ProtectedRoute>} />
                    <Route path="/cadastrar-pet" element={<ProtectedRoute isLoggedIn={isLoggedIn}><PetCadastroScreen onNavigateToHome={() => navigate('/')} /></ProtectedRoute>} />
                    
                    {/* Rota de fallback (página não encontrada) - Opcional */}
                    <Route path="*" element={<div>Página não encontrada</div>} />
                </Routes>
            </main>
        </div>
    );
}

export default App;
